std::atomic<bool> g_initialized;
thread_local bool g_initializedForThread;

void PromptToRestartExplorer(HRESULT statusCode) {
    // The upstream module offered to kill and restart Explorer from inside the
    // injected process. JARVIS2 keeps recovery out-of-process and behind the
    // supervisor's kill-switch/confirmation interlocks instead.
    Wh_Log(L"Explorer restart may be required; status code: 0x%08X",
           statusCode);
}

void ApplyCustomizations(InstanceHandle handle,
                         winrt::Windows::UI::Xaml::FrameworkElement element,
                         PCWSTR fallbackClassName);
void CleanupCustomizations(InstanceHandle handle);
bool IsJarvisActivationActive();
void LatchJarvisActivationQuiesced(PCWSTR reason) noexcept;
void RequirePermanentUnloadSafetyPin(PCWSTR reason) noexcept;
void FailClosedForeignAbiException(PCWSTR reason) noexcept;

template <typename Callback>
void RunProjectedCallbackNoThrow(
    PCWSTR failureReason,
    Callback&& callback) noexcept {
    try {
        std::forward<Callback>(callback)();
    } catch (...) {
        FailClosedForeignAbiException(failureReason);
    }
}

template <typename... Args>
void LogJarvisDiagnosticNoThrow(
    PCWSTR failureReason,
    PCWSTR format,
    Args&&... args) noexcept {
    try {
        // Wh_Log is a macro whose format operand must be a literal. This
        // helper deliberately accepts a runtime format, so preserve the same
        // disabled-log fast path and call Windhawk's variadic wrapper.
        if (InternalWh_IsLogEnabled(InternalWhModPtr)) {
            InternalWh_Log_Wrapper(
                format, std::forward<Args>(args)...);
        }
    } catch (...) {
        FailClosedForeignAbiException(failureReason);
    }
}

enum class RetainedKernelCapabilityKind : std::uint32_t {
    None,
    VisualTreeAdviseThread,
    VisualTreeUnadviseThread,
    UiThread,
    UiCleanupEvent,
    StateGate,
    ActivationPermit,
    KillSwitchWatcherThread,
    KillSwitchWatcherStopEvent,
    KillSwitchWatcherChangeNotification,
    StatsMutex,
    XamlRegistryNotificationEvent,
    XamlRegistryKey,
    XamlRegistryWait,
};

enum class RetainedKernelCapabilityDisposition : std::uint32_t {
    CloseFailed,
    ReleasePending,
    DeletePendingCloseFailed,
    MutexReleasePending,
    ChangeNotificationCloseFailed,
    RegistryKeyCloseFailed,
    RegistryWaitUnregisterPending,
    PublishedWaitDependencyRetained,
};

enum class KernelCapabilitySlotState : std::uint32_t {
    Empty,
    Reserved,
    LiveLocal,
    Retained,
};

enum class KernelCapabilityCloseOutcome : std::uint32_t {
    NoOwner,
    Closed,
    Transferred,
    StillOwned,
};

constexpr bool IsKernelCapabilityPhysicallyClosed(
    KernelCapabilityCloseOutcome outcome) noexcept {
    return outcome == KernelCapabilityCloseOutcome::NoOwner ||
           outcome == KernelCapabilityCloseOutcome::Closed;
}

constexpr PCWSTR ToString(
    KernelCapabilitySlotState state) noexcept {
    switch (state) {
    case KernelCapabilitySlotState::Empty:
        return L"empty";
    case KernelCapabilitySlotState::Reserved:
        return L"reserved";
    case KernelCapabilitySlotState::LiveLocal:
        return L"live-local";
    case KernelCapabilitySlotState::Retained:
        return L"retained";
    }
    return L"unknown";
}

constexpr PCWSTR ToString(
    RetainedKernelCapabilityKind kind) noexcept {
    switch (kind) {
    case RetainedKernelCapabilityKind::None:
        return L"none";
    case RetainedKernelCapabilityKind::VisualTreeAdviseThread:
        return L"visual-tree-advise-thread";
    case RetainedKernelCapabilityKind::VisualTreeUnadviseThread:
        return L"visual-tree-unadvise-thread";
    case RetainedKernelCapabilityKind::UiThread:
        return L"ui-thread";
    case RetainedKernelCapabilityKind::UiCleanupEvent:
        return L"ui-cleanup-event";
    case RetainedKernelCapabilityKind::StateGate:
        return L"state-gate";
    case RetainedKernelCapabilityKind::ActivationPermit:
        return L"activation-permit";
    case RetainedKernelCapabilityKind::KillSwitchWatcherThread:
        return L"kill-switch-watcher-thread";
    case RetainedKernelCapabilityKind::KillSwitchWatcherStopEvent:
        return L"kill-switch-watcher-stop-event";
    case RetainedKernelCapabilityKind::KillSwitchWatcherChangeNotification:
        return L"kill-switch-watcher-change-notification";
    case RetainedKernelCapabilityKind::StatsMutex:
        return L"stats-mutex";
    case RetainedKernelCapabilityKind::XamlRegistryNotificationEvent:
        return L"xaml-registry-notification-event";
    case RetainedKernelCapabilityKind::XamlRegistryKey:
        return L"xaml-registry-key";
    case RetainedKernelCapabilityKind::XamlRegistryWait:
        return L"xaml-registry-wait";
    }
    return L"unknown";
}

constexpr PCWSTR ToString(
    RetainedKernelCapabilityDisposition disposition) noexcept {
    switch (disposition) {
    case RetainedKernelCapabilityDisposition::CloseFailed:
        return L"close-failed";
    case RetainedKernelCapabilityDisposition::ReleasePending:
        return L"release-pending";
    case RetainedKernelCapabilityDisposition::DeletePendingCloseFailed:
        return L"delete-pending-close-failed";
    case RetainedKernelCapabilityDisposition::MutexReleasePending:
        return L"mutex-release-pending";
    case RetainedKernelCapabilityDisposition::
        ChangeNotificationCloseFailed:
        return L"change-notification-close-failed";
    case RetainedKernelCapabilityDisposition::RegistryKeyCloseFailed:
        return L"registry-key-close-failed";
    case RetainedKernelCapabilityDisposition::
        RegistryWaitUnregisterPending:
        return L"registry-wait-unregister-pending";
    case RetainedKernelCapabilityDisposition::
        PublishedWaitDependencyRetained:
        return L"published-wait-dependency-retained";
    }
    return L"unknown";
}

struct RetainedKernelCapabilityReceipt {
    HANDLE handle = nullptr;
    RetainedKernelCapabilityKind kind =
        RetainedKernelCapabilityKind::None;
    std::uint64_t ownerIdentity = 0;
    DWORD owningThreadId = 0;
    DWORD error = ERROR_SUCCESS;
    RetainedKernelCapabilityDisposition disposition =
        RetainedKernelCapabilityDisposition::CloseFailed;
    KernelCapabilitySlotState state =
        KernelCapabilitySlotState::Empty;
    // Opaque process-lifetime dependency proof. It is never dereferenced or
    // logged outside the typed registry-wait quarantine path.
    std::uintptr_t opaqueDependentContext = 0;
    std::uint64_t dependencyOwnerIdentity1 = 0;
    std::uint64_t dependencyOwnerIdentity2 = 0;
};

// The module admits at most 64 UI records. Their published, rollback and
// identity handles plus singleton watcher/state/stats owners fit this pool.
// XAML registry watches use the same pre-creation reservation and simply skip
// creating another OS owner when the remaining capacity is unavailable.
// A mapped module also admits only one initialization generation.
constexpr std::size_t kRetainedKernelCapabilityCapacity = 512;
std::atomic_flag g_retainedKernelCapabilityGate = ATOMIC_FLAG_INIT;
std::array<RetainedKernelCapabilityReceipt,
           kRetainedKernelCapabilityCapacity>
    g_retainedKernelCapabilities;
std::atomic<std::uint64_t>
    g_retainedKernelCapabilityOverflow{0};
std::atomic<std::uint64_t>
    g_kernelCapabilityOwnerTicket{0};

class RetainedKernelCapabilityGuard {
public:
    RetainedKernelCapabilityGuard() noexcept {
        while (g_retainedKernelCapabilityGate.test_and_set(
            std::memory_order_acquire)) {
            YieldProcessor();
        }
    }

    RetainedKernelCapabilityGuard(
        const RetainedKernelCapabilityGuard&) = delete;
    RetainedKernelCapabilityGuard& operator=(
        const RetainedKernelCapabilityGuard&) = delete;

    ~RetainedKernelCapabilityGuard() noexcept {
        g_retainedKernelCapabilityGate.clear(
            std::memory_order_release);
    }
};

std::uint64_t ClaimKernelCapabilityOwnerTicket() noexcept {
    std::uint64_t ticket =
        g_kernelCapabilityOwnerTicket.fetch_add(
            1, std::memory_order_acq_rel) +
        1;
    if (ticket == 0) {
        FailClosedForeignAbiException(
            L"kernel capability owner ticket wrapped");
        ticket =
            g_kernelCapabilityOwnerTicket.fetch_add(
                1, std::memory_order_acq_rel) +
            1;
    }
    return ticket;
}

std::uint64_t ReserveKernelCapability(
    RetainedKernelCapabilityKind kind,
    DWORD owningThreadId = 0) noexcept {
    if (kind == RetainedKernelCapabilityKind::None) {
        return 0;
    }

    const std::uint64_t ownerIdentity =
        ClaimKernelCapabilityOwnerTicket();
    if (ownerIdentity == 0) {
        return 0;
    }

    bool reserved = false;
    {
        RetainedKernelCapabilityGuard lock;
        for (auto& slot : g_retainedKernelCapabilities) {
            if (slot.state != KernelCapabilitySlotState::Empty) {
                continue;
            }
            slot.kind = kind;
            slot.ownerIdentity = ownerIdentity;
            slot.owningThreadId =
                owningThreadId != 0 ? owningThreadId
                                    : GetCurrentThreadId();
            slot.state = KernelCapabilitySlotState::Reserved;
            reserved = true;
            break;
        }
    }
    if (!reserved) {
        g_retainedKernelCapabilityOverflow.fetch_add(
            1, std::memory_order_acq_rel);
        FailClosedForeignAbiException(
            L"kernel capability reservation capacity was exhausted");
        return 0;
    }
    return ownerIdentity;
}

bool PublishKernelCapability(
    HANDLE handle,
    RetainedKernelCapabilityKind kind,
    std::uint64_t ownerIdentity) noexcept {
    if (!handle || handle == INVALID_HANDLE_VALUE ||
        kind == RetainedKernelCapabilityKind::None ||
        ownerIdentity == 0) {
        return false;
    }

    RetainedKernelCapabilityGuard lock;
    for (auto& slot : g_retainedKernelCapabilities) {
        if (slot.kind != kind ||
            slot.ownerIdentity != ownerIdentity) {
            continue;
        }
        if (slot.state == KernelCapabilitySlotState::LiveLocal &&
            slot.handle == handle) {
            return true;
        }
        if (slot.state != KernelCapabilitySlotState::Reserved ||
            slot.handle) {
            return false;
        }
        slot.handle = handle;
        slot.state = KernelCapabilitySlotState::LiveLocal;
        return true;
    }
    return false;
}

bool CancelKernelCapabilityReservation(
    RetainedKernelCapabilityKind kind,
    std::uint64_t ownerIdentity) noexcept {
    if (kind == RetainedKernelCapabilityKind::None ||
        ownerIdentity == 0) {
        return false;
    }

    RetainedKernelCapabilityGuard lock;
    for (auto& slot : g_retainedKernelCapabilities) {
        if (slot.kind != kind ||
            slot.ownerIdentity != ownerIdentity) {
            continue;
        }
        if (slot.state != KernelCapabilitySlotState::Reserved ||
            slot.handle) {
            return false;
        }
        slot = {};
        return true;
    }
    return false;
}

bool CompleteKernelCapabilityClose(
    HANDLE handle,
    RetainedKernelCapabilityKind kind,
    std::uint64_t ownerIdentity) noexcept {
    if (!handle || handle == INVALID_HANDLE_VALUE ||
        kind == RetainedKernelCapabilityKind::None ||
        ownerIdentity == 0) {
        return false;
    }

    RetainedKernelCapabilityGuard lock;
    for (auto& slot : g_retainedKernelCapabilities) {
        if (slot.kind != kind ||
            slot.ownerIdentity != ownerIdentity) {
            continue;
        }
        const bool exactLiveOwner =
            slot.state == KernelCapabilitySlotState::LiveLocal &&
            slot.handle == handle;
        const bool unpublishedReservedOwner =
            slot.state == KernelCapabilitySlotState::Reserved &&
            !slot.handle;
        if (!exactLiveOwner && !unpublishedReservedOwner) {
            return false;
        }
        slot = {};
        return true;
    }
    return false;
}

bool RetainKernelCapability(
    HANDLE handle,
    RetainedKernelCapabilityKind kind,
    std::uint64_t ownerIdentity,
    DWORD error,
    PCWSTR reason,
    RetainedKernelCapabilityDisposition disposition =
        RetainedKernelCapabilityDisposition::CloseFailed) noexcept {
    if (!handle || handle == INVALID_HANDLE_VALUE ||
        kind == RetainedKernelCapabilityKind::None ||
        ownerIdentity == 0) {
        return false;
    }

    bool retained = false;
    {
        RetainedKernelCapabilityGuard lock;
        for (auto& slot : g_retainedKernelCapabilities) {
            if (slot.kind != kind ||
                slot.ownerIdentity != ownerIdentity) {
                continue;
            }
            if (slot.state == KernelCapabilitySlotState::Retained &&
                slot.handle == handle) {
                slot.error = error;
                slot.disposition = disposition;
                retained = true;
                break;
            }
            if ((slot.state == KernelCapabilitySlotState::Reserved &&
                 !slot.handle) ||
                (slot.state == KernelCapabilitySlotState::LiveLocal &&
                 slot.handle == handle)) {
                slot.handle = handle;
                slot.error = error;
                slot.disposition = disposition;
                slot.state = KernelCapabilitySlotState::Retained;
                retained = true;
            }
            break;
        }
    }

    if (!retained) {
        g_retainedKernelCapabilityOverflow.fetch_add(
            1, std::memory_order_acq_rel);
        FailClosedForeignAbiException(
            L"kernel capability retained ledger was unavailable");
        return false;
    }
    RequirePermanentUnloadSafetyPin(reason);
    return true;
}

KernelCapabilityCloseOutcome CloseOrRetainKernelCapability(
    HANDLE* owner,
    RetainedKernelCapabilityKind kind,
    std::uint64_t ownerIdentity,
    PCWSTR reason,
    DWORD* closeError = nullptr,
    RetainedKernelCapabilityDisposition disposition =
        RetainedKernelCapabilityDisposition::CloseFailed) noexcept {
    if (closeError) {
        *closeError = ERROR_SUCCESS;
    }
    if (!owner || !*owner) {
        return KernelCapabilityCloseOutcome::NoOwner;
    }

    HANDLE handle = *owner;
    if (CloseHandle(handle)) {
        *owner = nullptr;
        if (!CompleteKernelCapabilityClose(
                handle, kind, ownerIdentity)) {
            FailClosedForeignAbiException(
                L"closed kernel capability reservation was missing");
        }
        return KernelCapabilityCloseOutcome::Closed;
    }

    const DWORD error = GetLastError();
    if (closeError) {
        *closeError = error;
    }
    if (RetainKernelCapability(
            handle, kind, ownerIdentity, error, reason,
            disposition)) {
        *owner = nullptr;
        return KernelCapabilityCloseOutcome::Transferred;
    }
    return KernelCapabilityCloseOutcome::StillOwned;
}

KernelCapabilityCloseOutcome CloseOrRetainChangeNotification(
    HANDLE* owner,
    std::uint64_t ownerIdentity,
    PCWSTR reason,
    DWORD* closeError = nullptr) noexcept {
    if (closeError) {
        *closeError = ERROR_SUCCESS;
    }
    if (!owner || *owner == INVALID_HANDLE_VALUE) {
        return KernelCapabilityCloseOutcome::NoOwner;
    }

    HANDLE handle = *owner;
    if (FindCloseChangeNotification(handle)) {
        *owner = INVALID_HANDLE_VALUE;
        if (!CompleteKernelCapabilityClose(
                handle,
                RetainedKernelCapabilityKind::
                    KillSwitchWatcherChangeNotification,
                ownerIdentity)) {
            FailClosedForeignAbiException(
                L"closed change-notification reservation was missing");
        }
        return KernelCapabilityCloseOutcome::Closed;
    }

    const DWORD error = GetLastError();
    if (closeError) {
        *closeError = error;
    }
    if (RetainKernelCapability(
            handle,
            RetainedKernelCapabilityKind::
                KillSwitchWatcherChangeNotification,
            ownerIdentity, error, reason,
            RetainedKernelCapabilityDisposition::
                ChangeNotificationCloseFailed)) {
        *owner = INVALID_HANDLE_VALUE;
        return KernelCapabilityCloseOutcome::Transferred;
    }
    return KernelCapabilityCloseOutcome::StillOwned;
}

KernelCapabilityCloseOutcome CloseOrRetainRegistryKey(
    HKEY* owner,
    std::uint64_t ownerIdentity,
    PCWSTR reason,
    LSTATUS* closeStatus = nullptr) noexcept {
    if (closeStatus) {
        *closeStatus = ERROR_SUCCESS;
    }
    if (!owner || !*owner) {
        return KernelCapabilityCloseOutcome::NoOwner;
    }

    HKEY key = *owner;
    const LSTATUS status = RegCloseKey(key);
    if (status == ERROR_SUCCESS) {
        *owner = nullptr;
        if (!CompleteKernelCapabilityClose(
                reinterpret_cast<HANDLE>(key),
                RetainedKernelCapabilityKind::XamlRegistryKey,
                ownerIdentity)) {
            FailClosedForeignAbiException(
                L"closed registry-key reservation was missing");
        }
        return KernelCapabilityCloseOutcome::Closed;
    }

    if (closeStatus) {
        *closeStatus = status;
    }
    if (RetainKernelCapability(
            reinterpret_cast<HANDLE>(key),
            RetainedKernelCapabilityKind::XamlRegistryKey,
            ownerIdentity, static_cast<DWORD>(status), reason,
            RetainedKernelCapabilityDisposition::
                RegistryKeyCloseFailed)) {
        *owner = nullptr;
        return KernelCapabilityCloseOutcome::Transferred;
    }
    return KernelCapabilityCloseOutcome::StillOwned;
}

bool BindXamlRegistryWaitBundle(
    std::uint64_t waitOwnerIdentity,
    std::uint64_t eventOwnerIdentity,
    std::uint64_t keyOwnerIdentity,
    void* opaqueContext) noexcept {
    if (waitOwnerIdentity == 0 || eventOwnerIdentity == 0 ||
        keyOwnerIdentity == 0 || !opaqueContext) {
        return false;
    }

    RetainedKernelCapabilityGuard lock;
    RetainedKernelCapabilityReceipt* waitSlot = nullptr;
    RetainedKernelCapabilityReceipt* eventSlot = nullptr;
    RetainedKernelCapabilityReceipt* keySlot = nullptr;
    for (auto& slot : g_retainedKernelCapabilities) {
        if (slot.ownerIdentity == waitOwnerIdentity &&
            slot.kind ==
                RetainedKernelCapabilityKind::XamlRegistryWait &&
            slot.state == KernelCapabilitySlotState::Reserved) {
            waitSlot = &slot;
        } else if (
            slot.ownerIdentity == eventOwnerIdentity &&
            slot.kind ==
                RetainedKernelCapabilityKind::
                    XamlRegistryNotificationEvent &&
            slot.state == KernelCapabilitySlotState::LiveLocal) {
            eventSlot = &slot;
        } else if (
            slot.ownerIdentity == keyOwnerIdentity &&
            slot.kind ==
                RetainedKernelCapabilityKind::XamlRegistryKey &&
            slot.state == KernelCapabilitySlotState::LiveLocal) {
            keySlot = &slot;
        }
    }
    if (!waitSlot || !eventSlot || !keySlot) {
        return false;
    }

    waitSlot->opaqueDependentContext =
        reinterpret_cast<std::uintptr_t>(opaqueContext);
    waitSlot->dependencyOwnerIdentity1 = eventOwnerIdentity;
    waitSlot->dependencyOwnerIdentity2 = keyOwnerIdentity;
    eventSlot->dependencyOwnerIdentity1 = waitOwnerIdentity;
    keySlot->dependencyOwnerIdentity1 = waitOwnerIdentity;
    return true;
}

bool RetainXamlRegistryWaitBundle(
    HANDLE waitHandle,
    std::uint64_t waitOwnerIdentity,
    HANDLE eventHandle,
    std::uint64_t eventOwnerIdentity,
    HKEY key,
    std::uint64_t keyOwnerIdentity,
    DWORD error,
    PCWSTR reason) noexcept {
    if (!waitHandle || waitHandle == INVALID_HANDLE_VALUE ||
        waitOwnerIdentity == 0 || !eventHandle ||
        eventHandle == INVALID_HANDLE_VALUE ||
        eventOwnerIdentity == 0 || !key ||
        keyOwnerIdentity == 0) {
        FailClosedForeignAbiException(
            L"registry wait bundle quarantine arguments were invalid");
        return false;
    }

    bool retained = false;
    {
        RetainedKernelCapabilityGuard lock;
        RetainedKernelCapabilityReceipt* waitSlot = nullptr;
        RetainedKernelCapabilityReceipt* eventSlot = nullptr;
        RetainedKernelCapabilityReceipt* keySlot = nullptr;
        for (auto& slot : g_retainedKernelCapabilities) {
            if (slot.ownerIdentity == waitOwnerIdentity &&
                slot.kind ==
                    RetainedKernelCapabilityKind::XamlRegistryWait &&
                ((slot.state == KernelCapabilitySlotState::Reserved &&
                  !slot.handle) ||
                 ((slot.state == KernelCapabilitySlotState::LiveLocal ||
                   slot.state == KernelCapabilitySlotState::Retained) &&
                  slot.handle == waitHandle))) {
                waitSlot = &slot;
            } else if (
                slot.ownerIdentity == eventOwnerIdentity &&
                slot.kind ==
                    RetainedKernelCapabilityKind::
                        XamlRegistryNotificationEvent &&
                (slot.state == KernelCapabilitySlotState::LiveLocal ||
                 slot.state == KernelCapabilitySlotState::Retained) &&
                slot.handle == eventHandle) {
                eventSlot = &slot;
            } else if (
                slot.ownerIdentity == keyOwnerIdentity &&
                slot.kind ==
                    RetainedKernelCapabilityKind::XamlRegistryKey &&
                (slot.state == KernelCapabilitySlotState::LiveLocal ||
                 slot.state == KernelCapabilitySlotState::Retained) &&
                slot.handle == reinterpret_cast<HANDLE>(key)) {
                keySlot = &slot;
            }
        }
        const bool exactBundle =
            waitSlot && eventSlot && keySlot &&
            waitSlot->opaqueDependentContext != 0 &&
            waitSlot->dependencyOwnerIdentity1 ==
                eventOwnerIdentity &&
            waitSlot->dependencyOwnerIdentity2 ==
                keyOwnerIdentity &&
            eventSlot->dependencyOwnerIdentity1 ==
                waitOwnerIdentity &&
            keySlot->dependencyOwnerIdentity1 ==
                waitOwnerIdentity;
        if (exactBundle) {
            waitSlot->handle = waitHandle;
            waitSlot->error = error;
            waitSlot->disposition =
                RetainedKernelCapabilityDisposition::
                    RegistryWaitUnregisterPending;
            waitSlot->state = KernelCapabilitySlotState::Retained;
            eventSlot->error = error;
            eventSlot->disposition =
                RetainedKernelCapabilityDisposition::
                    PublishedWaitDependencyRetained;
            eventSlot->state = KernelCapabilitySlotState::Retained;
            keySlot->error = error;
            keySlot->disposition =
                RetainedKernelCapabilityDisposition::
                    PublishedWaitDependencyRetained;
            keySlot->state = KernelCapabilitySlotState::Retained;
            retained = true;
        }
    }

    if (!retained) {
        FailClosedForeignAbiException(
            L"registry wait bundle quarantine invariant failed");
        return false;
    }
    RequirePermanentUnloadSafetyPin(reason);
    return true;
}

void LogRetainedKernelCapabilityReceipts() noexcept {
    std::array<RetainedKernelCapabilityReceipt,
               kRetainedKernelCapabilityCapacity>
        snapshot{};
    {
        RetainedKernelCapabilityGuard lock;
        snapshot = g_retainedKernelCapabilities;
    }

    std::uint32_t retainedCount = 0;
    std::uint32_t outstandingCount = 0;
    for (std::size_t index = 0; index < snapshot.size(); ++index) {
        const auto& receipt = snapshot[index];
        if (receipt.state == KernelCapabilitySlotState::Empty) {
            continue;
        }
        ++outstandingCount;
        if (receipt.state == KernelCapabilitySlotState::Retained) {
            ++retainedCount;
        }
        LogJarvisDiagnosticNoThrow(
            L"kernel capability receipt diagnostic threw",
            L"Kernel capability outstanding: slot=%u kind=%s "
            L"owner=%llu thread=%u state=%s error=%u disposition=%s",
            static_cast<unsigned>(index),
            ToString(receipt.kind),
            receipt.ownerIdentity,
            receipt.owningThreadId,
            ToString(receipt.state),
            receipt.error,
            ToString(receipt.disposition));
    }
    LogJarvisDiagnosticNoThrow(
        L"kernel capability summary diagnostic threw",
        L"Kernel capability summary: outstanding=%u retained=%u "
        L"overflow=%llu",
        outstandingCount, retainedCount,
        g_retainedKernelCapabilityOverflow.load(
            std::memory_order_acquire));
}

std::atomic<std::uint64_t>
    g_loaderReferenceReleaseFailures{0};

class NoThrowModuleReferenceOwner {
public:
    explicit NoThrowModuleReferenceOwner(
        PCWSTR releaseFailureReason) noexcept
        : m_releaseFailureReason(releaseFailureReason) {}

    NoThrowModuleReferenceOwner(
        const NoThrowModuleReferenceOwner&) = delete;
    NoThrowModuleReferenceOwner& operator=(
        const NoThrowModuleReferenceOwner&) = delete;

    ~NoThrowModuleReferenceOwner() noexcept {
        ReleaseNow();
    }

    bool AdoptConfirmed(HMODULE module) noexcept {
        if (!module || m_module) {
            return false;
        }
        m_module = module;
        return true;
    }

    [[nodiscard]] HMODULE get() const noexcept {
        return m_module;
    }

    [[nodiscard]] HMODULE Detach() noexcept {
        return std::exchange(m_module, nullptr);
    }

    bool ReleaseNow(
        DWORD* releaseError = nullptr,
        HMODULE* retainedModule = nullptr) noexcept {
        if (retainedModule) {
            *retainedModule = nullptr;
        }
        HMODULE module = std::exchange(m_module, nullptr);
        if (!module) {
            if (releaseError) {
                *releaseError = ERROR_SUCCESS;
            }
            return true;
        }

        if (FreeLibrary(module)) {
            if (releaseError) {
                *releaseError = ERROR_SUCCESS;
            }
            return true;
        }

        const DWORD error = GetLastError();
        if (releaseError) {
            *releaseError = error;
        }
        if (retainedModule) {
            *retainedModule = module;
        }
        const std::uint64_t failures =
            g_loaderReferenceReleaseFailures.fetch_add(
                1, std::memory_order_acq_rel) +
            1;

        // The loader reference may still exist, but its state isn't safe to
        // retry blindly. Publish pass-through before the unload-pin decision
        // gate can block, then retain a process-lifetime safety receipt.
        LatchJarvisActivationQuiesced(m_releaseFailureReason);
        RequirePermanentUnloadSafetyPin(m_releaseFailureReason);
        try {
            Wh_Log(
                L"Loader reference release was unconfirmed: module=%p "
                L"error=%u failures=%llu reason=%s",
                module, error, failures, m_releaseFailureReason);
        } catch (...) {
        }
        return false;
    }

private:
    HMODULE m_module = nullptr;
    PCWSTR m_releaseFailureReason = nullptr;
};

HMODULE GetCurrentModuleHandle() {
    HMODULE module;
    if (!GetModuleHandleEx(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                               GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                           L"", &module)) {
        return nullptr;
    }

    return module;
}

