#pragma region api_cpp

std::atomic<bool> g_inInjectWindhawkTAP{false};

class InjectWindhawkTapFlagGuard {
public:
    InjectWindhawkTapFlagGuard() noexcept
        : m_previous(g_inInjectWindhawkTAP.exchange(
              true, std::memory_order_acq_rel)) {}

    InjectWindhawkTapFlagGuard(
        const InjectWindhawkTapFlagGuard&) = delete;
    InjectWindhawkTapFlagGuard& operator=(
        const InjectWindhawkTapFlagGuard&) = delete;

    ~InjectWindhawkTapFlagGuard() noexcept {
        g_inInjectWindhawkTAP.store(
            m_previous, std::memory_order_release);
    }

private:
    bool m_previous;
};

using PFN_INITIALIZE_XAML_DIAGNOSTICS_EX = decltype(&InitializeXamlDiagnosticsEx);

HRESULT InjectWindhawkTAP() noexcept try
{
    TapLifecycleScope lifecycleScope(true,
                                     TapLifecycleEntryKind::kOperation);
    if (!lifecycleScope) {
        return HRESULT_FROM_WIN32(ERROR_CANCELLED);
    }

    if (!IsJarvisActivationActive())
    {
        return HRESULT_FROM_WIN32(ERROR_CANCELLED);
    }

    HMODULE module = GetCurrentModuleHandle();
    if (!module)
    {
        return HRESULT_FROM_WIN32(GetLastError());
    }

    WCHAR location[MAX_PATH];
    switch (GetModuleFileName(module, location, ARRAYSIZE(location)))
    {
    case 0:
    case ARRAYSIZE(location):
        return HRESULT_FROM_WIN32(GetLastError());
    }

    const HMODULE wux = LoadLibraryEx(
        L"Windows.UI.Xaml.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!wux) [[unlikely]]
    {
        return HRESULT_FROM_WIN32(GetLastError());
    }
    NoThrowModuleReferenceOwner wuxOwner(
        L"Windows.UI.Xaml loader reference couldn't be released");
    if (!wuxOwner.AdoptConfirmed(wux)) {
        LatchJarvisActivationQuiesced(
            L"Windows.UI.Xaml loader reference owner wasn't established");
        RequirePermanentUnloadSafetyPin(
            L"Windows.UI.Xaml loader reference owner wasn't established");
        return E_UNEXPECTED;
    }

    const auto ixde = reinterpret_cast<PFN_INITIALIZE_XAML_DIAGNOSTICS_EX>(GetProcAddress(wux, "InitializeXamlDiagnosticsEx"));
    if (!ixde) [[unlikely]]
    {
        DWORD error = GetLastError();
        return HRESULT_FROM_WIN32(error);
    }

    // I didn't find a better way than trying many connections until one works.
    // Reference:
    // https://github.com/microsoft/microsoft-ui-xaml/blob/d74a0332cf0d5e58f12eddce1070fa7a79b4c2db/src/dxaml/xcp/dxaml/lib/DXamlCore.cpp#L2782
    InjectWindhawkTapFlagGuard injectFlagGuard;

    HRESULT hr = HRESULT_FROM_WIN32(ERROR_CANCELLED);
    for (int i = 0; i < 10000; i++)
    {
        if (!IsJarvisActivationActive())
        {
            break;
        }

        WCHAR connectionName[256];
        wsprintf(connectionName, L"VisualDiagConnection%d", i + 1);

        hr = ixde(connectionName, GetCurrentProcessId(), L"", location, CLSID_WindhawkTAP, nullptr);
        if (hr != HRESULT_FROM_WIN32(ERROR_NOT_FOUND))
        {
            break;
        }
    }

    DWORD releaseError = ERROR_SUCCESS;
    if (!wuxOwner.ReleaseNow(&releaseError)) {
        if (SUCCEEDED(hr)) {
            hr = HRESULT_FROM_WIN32(releaseError);
        }
    }

    return hr;
}
catch (...)
{
    const HRESULT hr = winrt::to_hresult();
    FailClosedForeignAbiException(
        L"InjectWindhawkTAP function boundary threw");
    return FAILED(hr) ? hr : E_UNEXPECTED;
}

